D = {d['id']: d for d in PK['days']}
norm = lambda t: re.sub(r'\s+', ' ', t.replace('’', "'").replace('“', '"').replace('”', '"'))
TX = {k: norm(' '.join(l[1] for l in D[k]['passage'] if not re.match(r'^[❶-❿]$', l[1]))) for k in ('d1', 'd2', 'd3', 'd4')}
G = {k: [] for k in TX}
for s, ko, ex in S:
    full = norm(re.sub(r'\{([^|}]*)\|[^}]*\}', r'\1', s))
    where = [k for k in TX if full in TX[k]]; assert len(where) == 1, (full, where)
    for m in re.findall(r'\{([^}]*)\}', s): o = m.split('|'); assert len(o) == 2 and o[0] != o[1], s
    if '{' not in s: continue   # 괄호 없는 문장은 넣지 않음
    G[where[0]].append({'s': s, 'ko': ko, 'ex': ex})
nb = {k: sum(len(re.findall(r'\{', p['s'])) for p in v) for k, v in G.items()}
T = {'d1': '본문 ❶❷ · 카셀과 Beuys', 'd2': '본문 ❸❹ · 프로젝트 시작 · 반대', 'd3': '본문 ❺❻❼ · 함께 심은 숲', 'd4': 'Read More ❽ · 태안의 기적'}
day = {'id': 'gt5', 'name': '', 'range': '5과 본문 · 어법 선택 한 판', 'story': '5과 본문 어법 선택 한 판 · 괄호를 모두 맞혀야 100점 (덩이 4개)',
       'passage': sum((D[k]['passage'] for k in ('d1', 'd2', 'd3', 'd4')), []),
       'steps': [{'type': 'gate', 'title': '어법 선택 한 판', 'guide': "본문을 네 덩이로 나눴어요. 덩이마다 괄호를 모두 맞혀야 100점, 하나라도 틀리면 0점! 3번 안에 통과 못 하면 틀린 문장만 해설과 함께 연습하고 다시 도전해요.",
                  'items': [{'title': '%s (괄호 %d개)' % (T[k], nb[k]), 'parts': G[k]} for k in ('d1', 'd2', 'd3', 'd4')]}]}
PK['days'] = [d for d in PK['days'] if d['id'] != 'gt5'] + [day]
for i, d in enumerate(PK['days']): d['name'] = 'DAY %d' % (i + 1)
src = open(path, encoding='utf-8').read(); head = src[:src.index('window.PKG')]
if '한 판' not in head: head = head.rstrip('\n') + '\n/* 11/16: 5과 본문 어법 선택 한 판 DAY gt5 맨 끝 (generators/gen_h2c5gate.py) */\n'
write(PK, path, head)
